describe('Login to Sauce Demo Store', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should successfully log in with valid credentials and redirect to product catalogue', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in the login form
    cy.get('[data-testid="username"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Wait for the login API call to complete
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify redirection to product catalogue
    cy.url().should('include', '/inventory.html');
    cy.get('[data-testid="title"]').should('contain', 'Products');

    // Verify page title is visible
    cy.get('[data-testid="title"]').should('be.visible');

    // Verify inventory list is visible
    cy.get('[data-testid="inventory-container"]').should('be.visible');
    cy.get('[data-testid="inventory-list"]').should('be.visible');

    // Verify first item is visible
    cy.get('[data-testid="inventory-item"]').first().should('be.visible');
  });

  it('should display error message when login fails due to invalid credentials', () => {
    // Fill in the login form with invalid credentials
    cy.get('[data-testid="username"]').type('invalid_user');
    cy.get('[data-testid="password"]').type('wrong_password');
    cy.get('[data-testid="login-button"]').click();

    // Wait for the login API call to complete
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(401);
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid username or password');

    // Verify login button is still visible for retry
    cy.get('[data-testid="login-button"]').should('be.visible');
  });
});
